mapper.select:
SELECT tenant_id, principal_type, principal_id, workspace_id, mode
FROM coding_workspace_access
WHERE tenant_id = #{tenantId} AND principal_type = #{principalType}
  AND principal_id = #{principalId} AND workspace_id = #{workspaceId}

mapper.delete:
DELETE FROM coding_workspace_access
WHERE tenant_id = #{tenantId} AND principal_type = #{principalType}
  AND principal_id = #{principalId} AND workspace_id = #{workspaceId}
